# 依月份篩選：日期屬於查詢的月份就印「是」
date, query = input().split()
if date.startswith(query):
    print("是")
else:
    print("否")

# 最長連續打卡
record = input().strip()
best = 0      # 目前最長的連續天數
streak = 0    # 現在連續了幾天
for day in record:
    if day == "O":
        streak = streak + 1
    else:
        if streak > best:
            best = streak
        streak = 0
print(best)

# 質數判斷
n = int(input())
is_prime = True
for d in range(2, n // 2):
    if n % d == 0:
        is_prime = False
        break
if is_prime:
    print("是質數")
else:
    print("不是質數")

# 有沒有人不及格
def has_fail(scores):
    for s in scores:
        if s < 60:
            return True
        else:
            return False


scores = [int(x) for x in input().split()]
if has_fail(scores):
    print("有人不及格")
else:
    print("全部及格")

# 略過壞資料的加總
total = 0
skipped = 0
try:
    for word in input().split():
        total = total + int(word)
except ValueError:
    skipped = skipped + 1
print(f"總和 {total}，略過 {skipped} 個")

class Account:
    def __init__(self, balance):
        self.balance = balance

    def withdraw(self, amount):
        if amount <= 0:
            return "金額無效"
        if amount > self.balance:
            return "餘額不足"
        balance = self.balance - amount
        return f"領出 {amount} 元"


account = Account(100)
message = account.withdraw(int(input()))
print(f"{message}，餘額 {account.balance} 元")
